def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    if n >= 97:
        return 'D'

    opp_d = sum(1 for _, o in history if o == 'D')
    opp_c = n - opp_d

    last_me, last_opp = history[-1]

    if last_me == 'D' and last_opp == 'C':
        return 'D'
    if opp_d == 0 and n >= 10:
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    recent = history[-10:]
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    if recent_opp_d >= 5:
        return 'D'
    if recent_opp_d >= 3 and recent_opp_d > len(recent) - recent_opp_d:
        return 'D'

    if last_opp == 'D':
        if len(history) >= 2 and history[-2][1] == 'C':
            return 'C'
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break
        if streak == 2:
            return 'D'
        if streak <= 4:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        if opp_c >= opp_d:
            return 'C'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    return 'C'
